const D=window.ANALYTICS,$=id=>document.getElementById(id),fmt=n=>n.toLocaleString('en-US'),pct=(n,d)=>d?(100*n/d).toFixed(1)+'%':'N/A';
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
for(const [id,index,title]of [['month',0,'All months'],['product',1,'All account types'],['issue',2,'All issues']]){const values=[...new Set(D.cube.map(r=>r[index]))].sort();$(id).innerHTML='<option value="">'+title+'</option>'+values.map(v=>'<option value="'+escapeHtml(v)+'">'+escapeHtml(v)+'</option>').join('');$(id).addEventListener('change',render);}
function cohort(){return D.cube.filter(r=>(!$('month').value||r[0]===$('month').value)&&(!$('product').value||r[1]===$('product').value)&&(!$('issue').value||r[2]===$('issue').value));}
function aggregate(rows,index){const result={};for(const r of rows){const k=r[index];if(!result[k])result[k]={n:0,yes:0,known:0};result[k].n+=r[5];result[k].yes+=r[4]==='Yes'?r[5]:0;result[k].known+=['Yes','No'].includes(r[4])?r[5]:0;}return Object.entries(result).sort((a,b)=>b[1].n-a[1].n);}
function rank(rows,index,total){return aggregate(rows,index).map(([k,v])=>'<div class="rank"><div class="top"><span>'+escapeHtml(k)+'</span><b>'+fmt(v.n)+' · '+pct(v.n,total)+'</b></div><div class="track"><div class="fill" style="width:'+(100*v.n/(total||1))+'%"></div></div></div>').join('')||'<p class="empty">No matching complaints.</p>';}
function render(){const rows=cohort(),n=rows.reduce((a,r)=>a+r[5],0),yes=rows.reduce((a,r)=>a+(r[4]==='Yes'?r[5]:0),0),known=rows.reduce((a,r)=>a+(['Yes','No'].includes(r[4])?r[5]:0),0),issues=aggregate(rows,2);$('scope').textContent=fmt(n)+' complaints selected out of '+fmt(D.n)+' validated records.';$('metrics').innerHTML=[['Complaints',fmt(n),'Unique complaint records'],['Timely response',pct(yes,known),fmt(known)+' known responses'],['Not timely',fmt(known-yes),'Reported No responses'],['Largest issue share',issues.length?pct(issues[0][1].n,n):'N/A',issues.length?issues[0][0]:'No matching records']].map(([label,value,note])=>'<div class="kpi"><small>'+label+'</small><strong>'+value+'</strong><small>'+escapeHtml(note)+'</small></div>').join('');const monthly=Object.fromEntries(aggregate(rows,0));let max=Math.max(1,...Object.values(monthly).map(v=>v.n));$('trend').innerHTML=Array.from({length:12},(_,i)=>{const m='2025-'+String(i+1).padStart(2,'0'),v=monthly[m]?.n||0;return '<div class="col"><span>'+(v>=1000?(v/1000).toFixed(1)+'k':fmt(v))+'</span><div class="bar" style="height:'+(175*v/max)+'px" title="'+m+': '+fmt(v)+'"></div><small>'+new Date(2025,i,1).toLocaleString('en-US',{month:'short'})+'</small></div>';}).join('');$('ranking').innerHTML=rank(rows,2,n);$('responses').innerHTML=rank(rows,3,n);$('table').innerHTML=issues.map(([k,v])=>'<tr><td>'+escapeHtml(k)+'</td><td>'+fmt(v.n)+'</td><td>'+pct(v.n,n)+'</td><td>'+pct(v.yes,v.known)+'</td></tr>').join('')||'<tr><td colspan="4">No matching complaints.</td></tr>';}
$('reset').onclick=()=>{for(const id of ['month','product','issue'])$(id).value='';render();};
$('export').onclick=()=>{const rows=cohort(),n=rows.reduce((a,r)=>a+r[5],0),quote=s=>'"'+String(s).replaceAll('"','""')+'"',csv=['issue,complaints,share_pct,timely_response_pct',...aggregate(rows,2).map(([k,v])=>[quote(k),v.n,n?(100*v.n/n).toFixed(4):'',v.known?(100*v.yes/v.known).toFixed(4):''].join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='complaint-issue-summary.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('quality').innerHTML='<p>'+fmt(D.raw)+' downloaded → '+fmt(D.n)+' retained</p><p>'+D.duplicates+' duplicate IDs · '+D.rejected+' outside date/product scope</p><p>'+fmt(D.n-D.knownTimely)+' unknown timely-response values</p>';
const allIssues=aggregate(D.cube,2),monthly=Object.fromEntries(aggregate(D.cube,0)),dec=monthly['2025-12'].n,nov=monthly['2025-11'].n;
$('insights').innerHTML=[['Account management first',allIssues[0][0]+' represents '+pct(allIssues[0][1].n,D.n)+' of the cohort. Inspect sub-issues and customer journeys; track issue share and verified repeat contacts after any intervention.'],['Validate the January spike',fmt(monthly['2025-01'].n)+' complaints arrived in January. Check date clustering, company concentration, and source changes before drawing a causal conclusion.'],['Timeliness is only one signal','Overall timely response is '+pct(D.timelyYes,D.knownTimely)+'. December volume rose '+((dec/nov-1)*100).toFixed(1)+'% vs November. Pair complaint signals with internal resolution and satisfaction data before setting CX priorities.']].map(([title,text])=>'<article><h3>'+title+'</h3><p>'+escapeHtml(text)+'</p></article>').join('');render();
